/* PRIME product prototype. Dated source data; editorial examples are simulations. */
(()=>{'use strict';
const D=window.PRIME_DATA,E=window.PrimeEditorial,$=s=>document.querySelector(s),main=$('#main');
const fmt=(v,n=1)=>v==null?'—':Number(v).toLocaleString('bg-BG',{minimumFractionDigits:n,maximumFractionDigits:n});
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v+'T12:00:00Z').toLocaleDateString('bg-BG',{day:'numeric',month:'long'});
const markets={over25:'Над 2.5 гола',under25:'Под 2.5 гола',btts_yes:'Гол/гол — Да',btts_no:'Гол/гол — Не',home_over15:'Домакин над 1.5 гола',away_over15:'Гост над 1.5 гола'};
const today=D.fixtures.filter(f=>f.date===D.date),lead=today.find(f=>f.league_id==='bl1')||today[0]||D.fixtures[0];
const secondary=today.filter(f=>f.id!==lead.id);let fixtureDate=D.date,leagueFilter='all',search='',matchTab='analysis',recordDemo=false,selected=new Set(),reviewText='',review=null,reviewErrors=[],simulatedApproval=false,selectionsInitialized=false;
const demoRecord=[
 {id:'D01',name:'Примерен двубой 01',market:'over25',score:'2 : 1',odds:1.8,result:'win',audience:'FREE'},
 {id:'D02',name:'Примерен двубой 02',market:'btts_yes',score:'2 : 0',odds:1.85,result:'loss',audience:'CLUB'},
 {id:'D03',name:'Примерен двубой 03',market:'under25',score:'1 : 0',odds:1.75,result:'win',audience:'FREE'},
 {id:'D04',name:'Примерен двубой 04',market:'home_over15',score:'1 : 2',odds:1.9,result:'loss',audience:'CLUB'},
 {id:'D05',name:'Примерен двубой 05',market:'over25',score:'2 : 2',odds:1.9,result:'win',audience:'CLUB'},
 {id:'D06',name:'Примерен двубой 06',market:'btts_no',score:'1 : 1',odds:1.8,result:'loss',audience:'FREE'},
 {id:'D07',name:'Примерен двубой 07',market:'over25',score:'Отложен',odds:1.8,result:'void',audience:'CLUB'}
];
function badge(t,cls=''){return `<span class="label ${cls}">${t}</span>`;}
function crest(team,small=false){return `<span class="crest ${small?'small':''}" aria-hidden="true">${esc(team.short)}</span>`;}
function pair(f){return `<div class="club-pair" aria-label="Типографски маркери, не официални емблеми">${crest(f.home)}${crest(f.away)}</div>`;}
function pitch(){return `<svg class="pitch-decoration" viewBox="0 0 240 210" fill="none" stroke="currentColor" stroke-width="1"><rect x="5" y="5" width="230" height="200" rx="1"/><path d="M5 105h230M80 5v35h80V5M80 205v-35h80v35M100 5v14h40V5M100 205v-14h40v14"/><circle cx="120" cy="105" r="28"/><circle cx="120" cy="105" r="2" fill="currentColor"/></svg>`;}
function line(){return `<div class="edition-line"><span><strong>ПЕТЪК, 23 ОКТОМВРИ 2026</strong><span class="dot"></span>ИЗДАНИЕ № 001 · ДЕМО</span><span>Фокус: голови пазари<span class="dot"></span>София</span></div>`;}
function note(){return `<aside class="right-column"><section class="editor-note"><p class="eyebrow">ОТ РЕДАКЦИЯТА</p><h2>Добрата селекция<br>започва с добър въпрос.</h2><p>Къде има футболна логика за голове? Какво може да я провали? И заслужава ли си цената?</p><div class="signature"><span class="avatar">P</span><span>PRIME / Редакторски подход</span></div></section><section class="small-club">${badge('PRIME CLUB','outline')}<h3>Още проучване.<br>Същият стандарт.</h3><p>Допълнителни голови селекции и частен бриф, когато има достатъчно аргументи.</p><a class="text-link" href="#club">Виж концепцията <span>↗</span></a></section></aside>`;}
function matchCard(f,i){const club=i===0;return `<a class="match-card" href="#match/${encodeURIComponent(f.id)}"><div class="card-meta"><span>${esc(f.league)} · ${esc(f.time)}</span>${badge(club?'CLUB · ПРИМЕР':'НАБЛЮДАВАМЕ',club?'club':'gray')}</div><div class="card-teams"><div class="mini-pair">${crest(f.home,true)}${crest(f.away,true)}</div><h3>${esc(f.home.name)}<br><span>${esc(f.away.name)}</span></h3></div><div class="card-bottom"><div>${club?'Голов пазар · редакторски пример':'Очаква футболна проверка'}<small>${club?'Изследователска теза, без проверена цена':'Календарът не е препоръка'}</small></div><span class="card-arrow">↗</span></div></a>`;}
function renderToday(){main.innerHTML=`${line()}<div class="title-line"><div><p class="eyebrow">ПОДБРАНО. ПРОУЧЕНО. ОБЯСНЕНО.</p><h1>Футболът зад<br><em>добрата селекция.</em></h1></div><p>Кратък бриф за головите пазари.<br>Конкретна теза, важните доказателства<br>и рискът, който не премълчаваме.</p></div><div class="issue-grid"><div><article class="lead-card">${pitch()}<div class="lead-top">${badge('FREE · ПРИМЕРЕН АНАЛИЗ')}<span>${esc(lead.league)} · ${esc(lead.time)} ч.</span></div><div class="match-hero"><div class="hero-teams"><div class="time-info"><b>ВОДЕЩА ТЕЗА</b><span>23 октомври</span></div><h2>${esc(lead.home.name)}<span>${esc(lead.away.name)}</span></h2></div>${pair(lead)}</div><div class="selection-row"><div><small>ДЕМОНСТРАЦИОНЕН ГОЛОВ ПАЗАР</small><strong>Над 2.5 гола</strong></div><div class="price-pill"><small>ПРИМЕРЕН ПРАГ</small>1.80</div></div><p class="lead-summary">Търсим отворен двубой. Историята дава отправна точка; съставите, игровият план и актуалната цена трябва да потвърдят тезата.</p><div class="lead-footer"><span>Няма публикувана прогноза.<br>Селекцията е дизайнерски пример.</span><a href="#match/${encodeURIComponent(lead.id)}">Прочети разбора <b>↗</b></a></div></article><div class="section-heading"><h2>Още от изданието</h2><a class="text-link" href="#fixtures">Цялата програма <span>↗</span></a></div><div class="cards-grid">${secondary.slice(0,2).map(matchCard).join('')}</div></div>${note()}</div><div class="trust-strip"><span><strong><b>01 /</b> Една селекция. Ясна теза.</strong>Причина, доказателства и конкретен риск.</span><span><strong><b>02 /</b> Пълен отчет.</strong>Печеливши, губещи и анулирани. Заедно.</span><span><strong><b>03 /</b> Качеството определя обема.</strong>В някои дни правилният бриф е без селекция.</span></div>`;}
function dates(){return [...new Set(D.fixtures.map(f=>f.date))].slice(0,12);}
function renderFixtures(){const filtered=D.fixtures.filter(f=>f.date===fixtureDate&&(leagueFilter==='all'||f.league_id===leagueFilter)&&(`${f.home.name} ${f.away.name} ${f.home.source_name} ${f.away.source_name}`).toLowerCase().includes(search.toLowerCase()));const groups=['bl1','bl2'].map(l=>({l,fs:filtered.filter(f=>f.league_id===l)})).filter(g=>g.fs.length);main.innerHTML=`<div class="page-top"><div><p class="eyebrow">КАЛЕНДАРЪТ, С КОНТЕКСТ</p><h1 class="page-title">Предстоящият футбол.</h1><p class="subhead">Реална датирана програма за двете германски лиги. Един поглед показва кои двубои имат история за проучване.</p></div>${badge('72 МАЧА · SNAPSHOT','outline')}</div><div class="fixture-date">${dates().map(d=>`<button class="day-button ${d===fixtureDate?'active':''}" data-action="date" data-date="${d}">${new Date(d+'T12:00:00Z').toLocaleDateString('bg-BG',{weekday:'short'})}<strong>${+d.slice(-2)}</strong>${d.slice(5,7)==='11'?'ноември':'октомври'}</button>`).join('')}</div><div class="toolbar"><div class="segmented" aria-label="Първенство"><button data-action="league" data-league="all" class="${leagueFilter==='all'?'active':''}">Всички</button><button data-action="league" data-league="bl1" class="${leagueFilter==='bl1'?'active':''}">Бундеслига</button><button data-action="league" data-league="bl2" class="${leagueFilter==='bl2'?'active':''}">Бундеслига 2</button></div><label class="visually-hidden" for="search">Търси отбор</label><input id="search" class="field search" type="search" placeholder="Търси отбор…" value="${esc(search)}"></div><div id="fixture-results">${groups.map(g=>`<div class="list-header"><span>Германия / ${g.l==='bl1'?'Бундеслига':'Бундеслига 2'}</span><span>${g.fs.length} срещи</span></div>${g.fs.map(f=>`<a href="#match/${encodeURIComponent(f.id)}" class="fixture-row"><div class="fixture-time">${esc(f.time)}<small>София</small></div><div class="fixture-teams">${crest(f.home,true)}<div class="fixture-names">${esc(f.home.name)}<br>${esc(f.away.name)}</div></div><div class="fixture-tag">История: ${f.home_stats.n} + ${f.away_stats.n} мача<span>Няма проверена цена</span></div><span class="card-arrow">↗</span></a>`).join('')}`).join('')||'<div class="empty"><h2>Няма срещи за този филтър.</h2><p>Избери друга дата или премахни търсенето.</p></div>'}</div><p class="notice" style="margin-top:24px">Календар към ${date(D.date)} 2026 г. Последните отборни мачове са реални; актуални състави, контузии, xG и котировки не са заредени. Това е датирана демонстрация.</p>`;}
function findMatch(){return D.fixtures.find(f=>f.id===decodeURIComponent(location.hash.split('/')[1]||''))||lead;}
function renderMatch(){const f=findMatch(),demoPick=f.id===lead.id;main.innerHTML=`<a class="back-link" href="#today">← Обратно към изданието</a><div class="detail-grid"><div><header class="detail-banner">${pitch()}<div class="lead-top"><span>${esc(f.league)} · ${date(f.date)} · ${esc(f.time)} ч.</span>${badge(demoPick?'FREE · ПРИМЕР':'ЗА ПРОУЧВАНЕ')}</div><div class="match-hero"><div class="hero-teams"><p class="eyebrow" style="color:#b8caaa">ПРЕДИ ПЪРВИЯ СИГНАЛ</p><h1>${esc(f.home.name)}<span>${esc(f.away.name)}</span></h1></div>${pair(f)}</div></header><nav class="match-tabs" aria-label="Съдържание на мача"><button class="${matchTab==='analysis'?'active':''}" data-action="matchtab" data-tab="analysis">Разборът</button><button class="${matchTab==='numbers'?'active':''}" data-action="matchtab" data-tab="numbers">Числата</button><button class="${matchTab==='sources'?'active':''}" data-action="matchtab" data-tab="sources">Източниците</button></nav>${matchTab==='analysis'?analysis(f):matchTab==='numbers'?numbers(f):sources(f)}</div><aside class="detail-aside"><section class="pick-panel">${badge(demoPick?'РЕДАКТОРСКИ ПРИМЕР':'КАНДИДАТ ЗА ПРОУЧВАНЕ','amber')}<h2>${demoPick?'Над 2.5<br>общо гола':'Все още<br>без селекция'}</h2><p>${demoPick?'Демонстрира как изглежда една обоснована селекция. Примерният праг не е намерен коефициент.':'Присъствието в календара и добрата история са начало на проучването.'}</p><div class="spec-row"><span>Цена в момента</span><b class="amber">Непроверена</b></div><div class="spec-row"><span>Състави и отсъствия</span><b class="amber">Очакват проверка</b></div><div class="spec-row"><span>Историческа извадка</span><b>${f.home_stats.n} + ${f.away_stats.n} мача</b></div><div class="spec-row"><span>Статус на публикацията</span><b>Непубликувано</b></div><button class="btn primary full" style="margin-top:15px" data-action="packet-one" data-id="${esc(f.id)}">Изтегли пакет за анализ <span>↓</span></button></section><p class="aside-note">Моделна вероятност се показва само след отделна проверка на модела. Историческите честоти не са „AI увереност“.</p></aside></div>`;}
function analysis(f){return `<article class="article"><p class="eyebrow">ПРИМЕРЕН РЕДАКТОРСКИ ТЕКСТ</p><p class="intro">Головете започват от сценария за мача. Числата са първата проверка.</p><p>За този двубой имаме история от ${f.home_stats.n} мача на ${esc(f.home.name)} и ${f.away_stats.n} на ${esc(f.away.name)} в същото първенство. Тя е изчислена преди началния час, без резултата на предстоящата среща.</p><h2>Какво вече знаем</h2><div class="evidence"><span class="evidence-number">01</span><div><strong>Отбелязани голове в последните налични мачове</strong><p>${esc(f.home.name)}: ${fmt(f.home_stats.gf,2)} на мач. ${esc(f.away.name)}: ${fmt(f.away_stats.gf,2)}. Това е описание на извадката, не очакван резултат.</p></div></div><div class="evidence"><span class="evidence-number">02</span><div><strong>Мачовете с поне три гола</strong><p>За домакина: ${f.home_stats.over25} от ${f.home_stats.n}. За госта: ${f.away_stats.over25} от ${f.away_stats.n}. Не ги превръщаме механично в шанс за тази среща.</p></div></div><div class="evidence"><span class="evidence-number">03</span><div><strong>Следващата проверка е футболна</strong><p>Кой ще започне в атака? Има ли ротация, отсъствия или причина за различен игрови план? Тези въпроси още нямат проверен отговор в демонстрацията.</p></div></div><div class="risk"><strong>КАКВО МОЖЕ ДА ОБЕЗСИЛИ ТЕЗАТА</strong><p>Състав или игрови план, който променя очакваното темпо. Без потвърден контекст и актуална цена този пример остава непубликуван.</p></div></article>`;}
function numbers(f){const h=f.home_stats,a=f.away_stats;const rows=[['Брой мачове',h.n,a.n],['Отбелязани / мач',fmt(h.gf,2),fmt(a.gf,2)],['Допуснати / мач',fmt(h.ga,2),fmt(a.ga,2)],['Над 2.5 гола',`${h.over25} / ${h.n}`,`${a.over25} / ${a.n}`],['Гол/гол',`${h.btts} / ${h.n}`,`${a.btts} / ${a.n}`],['Домакин / гост извадка',f.home_venue.n,f.away_venue.n],['xG','Няма данни','Няма данни']];return `<article class="article"><p class="notice green">Реални резултати от OpenLigaDB. Последни до 10 мача в същата лига, преди този двубой. При новак в лигата извадката може да е по-малка.</p><table class="metric-table"><thead><tr><th>Исторически показател</th><th>${esc(f.home.name)}</th><th>${esc(f.away.name)}</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${r[0]}</td><td>${i===1?'<strong>':''}${r[1]}${i===1?'</strong>':''}</td><td>${i===1?'<strong>':''}${r[2]}${i===1?'</strong>':''}</td></tr>`).join('')}</tbody></table><div class="history-cols">${[h,a].map((p,i)=>`<section><h3>${esc(i===0?f.home.name:f.away.name)}</h3>${p.matches.slice(0,5).map(m=>`<div class="history-game"><span>${esc(m.home)} – ${esc(m.away)}<br><small>${m.date}</small></span><b>${m.score.join(' : ')}</b></div>`).join('')}</section>`).join('')}</div><p>Няма добавена статистика за удари или xG. Използваните имена са свързани с постоянните ID на отборите в OpenLigaDB.</p></article>`;}
function sources(f){return `<article class="article"><div class="source-card"><h3>01 / Резултати и програма</h3><p>OpenLigaDB · общностен източник с постоянен ID на срещата: <strong>${esc(f.id)}</strong>.</p><a href="${esc(f.source_url)}" target="_blank" rel="noopener">${esc(f.source_url)} ↗</a><p>Получени: ${esc(D.fetched_utc)}. Данните са под ODbL. Това е време на нашето изтегляне, а не гаранция кога е променен всеки факт.</p></div><div class="source-card"><h3>02 / Футболен контекст</h3><p>Няма проверени новини за състави, отсъствия и ротация. В работната версия всеки съществен факт ще има URL, дата на публикация и час на проверката.</p>${badge('ОЧАКВА ПРОУЧВАНЕ','amber')}</div><div class="source-card"><h3>03 / Пазарна цена</h3><p>Няма получена актуална котировка. Примерният праг 1.80 на началния екран е дизайнерска стойност, а не проверена цена или доказано предимство.</p>${badge('БЛОКИРА ПУБЛИКУВАНЕТО','amber')}</div><p>Авторският текст е демонстрационен. Няма извършен журналистически или AI анализ на актуални новини за този мач.</p></article>`;}
function renderRecord(){const rows=recordDemo?demoRecord:[],s=E.recordStats(rows);main.innerHTML=`<div class="page-top"><div><p class="eyebrow">ДОВЕРИЕТО СЕ НАТРУПВА</p><h1 class="page-title">Целият ни отчет.</h1><p class="subhead">Всеки публикуван избор остава в архива. Показваме цената при публикуване, резултата и всички последващи корекции.</p></div><button class="btn" data-action="export-record">Изтегли ${recordDemo?'демо ':''}CSV ↓</button></div><div class="toolbar"><div class="segmented"><button data-action="record-real" class="${!recordDemo?'active':''}">Реални публикации</button><button data-action="record-demo" class="${recordDemo?'active':''}">Примерен отчет</button></div>${badge(recordDemo?'ИЗМИСЛЕНИ ДАННИ':'НЯМА ПУБЛИКУВАНИ ПРОГНОЗИ',recordDemo?'amber':'gray')}</div><div class="record-stats"><div><small>ПУБЛИКАЦИИ</small><strong>${s.n}</strong></div><div><small>РЕЗУЛТАТ ПРИ 1 ЕДИНИЦА</small><strong class="${s.profit<0?'negative':''}">${s.settled?fmt(s.profit,2)+' u':'—'}</strong></div><div><small>YIELD · ${s.settled} РЕШЕНИ</small><strong class="${s.profit<0?'negative':''}">${s.yield==null?'—':fmt(s.yield*100,1)+'%'}</strong></div><div><small>АНУЛИРАНИ</small><strong>${s.voids}</strong></div></div>${!recordDemo?'<div class="empty"><div class="empty-icon">∅</div><h2>Архивът започва от първата публикация.</h2><p>Този прототип няма реална типстърска история. Можеш да разгледаш примерния отчет, за да видиш как ще се показват и загубите.</p><button class="btn primary" data-action="record-demo">Виж примерния отчет ↗</button></div>':`<p class="notice">Всички записи по-долу са измислени примери за интерфейса. Не са предматчови прогнози и не измерват резултатите на PRIME.</p><div class="table-overflow"><table class="ledger"><thead><tr><th>ПРИМЕР</th><th>СЕЛЕКЦИЯ / ДОСТЪП</th><th>ЦЕНА</th><th>РЕЗУЛТАТ</th><th>ОТЧЕТ</th><th>ЕДИНИЦИ</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}<br><small class="muted">${r.id} · СИНТЕТИЧЕН ЗАПИС</small></td><td>${markets[r.market]}<br><small class="muted">${r.audience}</small></td><td>${fmt(r.odds,2)}</td><td>${r.score}</td><td><span class="result-pill ${r.result}">${{win:'Печеливша',loss:'Губеща',void:'Анулирана'}[r.result]}</span></td><td class="${r.result==='loss'?'negative':r.result==='win'?'positive':''}">${fmt(r.result==='win'?r.odds-1:r.result==='loss'?-1:0,2)}</td></tr>`).join('')}</tbody></table></div>`}<div class="record-rules"><section><h3>Как отчитаме</h3><p>Фиксирана 1 единица на единична селекция. Yield = нетен резултат / вложени единици в решените селекции. Анулираните записи се показват отделно. FREE, Club и комбинациите имат отделни отчети в работната версия.</p></section><section><h3>Как пазим историята</h3><p>Одобреният текст, пазарът и цената се запазват с час на публикуване. Поправка добавя ново събитие и причина. Подписът на файла помага за проверката на промените; сам по себе си не е независима типстърска верификация.</p></section></div>`;}
function renderClub(){main.innerHTML=`<div class="club-hero"><p class="eyebrow">PRIME CLUB / КОНЦЕПЦИЯ ЗА АБОНАМЕНТ</p><h1 class="page-title">Повече контекст.<br><em>Същата дисциплина.</em></h1><p>Допълнителното проучване има стойност. Броят прогнози сам по себе си няма. Един стандарт за целия PRIME.</p></div><div class="pricing-grid"><section class="pricing-card"><h2>Изданието</h2><div class="price">€0<span> / винаги</span></div><p class="price-caption">Свободен достъп до основния бриф.</p><ul><li>Пълна FREE селекция, когато има основание</li><li>Теза, доказателства и основен риск</li><li>Реална програма и публичен архив</li><li>Дни без селекция, когато е необходимо</li></ul><a href="#today" class="btn full">Разгледай изданието ↗</a></section><section class="pricing-card featured"><div class="card-meta"><h2 style="color:#fff">PRIME Club</h2>${badge('ПРЕДЛОЖЕН МОДЕЛ')}</div><div class="price">€9<span> / месец</span></div><p class="price-caption">Начална ценова хипотеза. Продажби не са активни.</p><ul><li>Допълнителни проучени голови селекции</li><li>Отборни голове и гол/гол при добра цена</li><li>Подробният бриф в частен Telegram</li><li>Всички резултати в публичния отчет</li></ul><button class="btn light full" data-action="club-info">Как би работил достъпът ↗</button></section></div><p class="club-principle"><strong>Качеството не се заключва зад абонамента.</strong><br>Club добавя още проучване, когато има стойностни възможности. Няма дневна квота, „сигурни“ мачове или обещана доходност. До старта на реалния регистър абонамент не се предлага.</p><div class="record-rules" style="max-width:850px;margin:30px auto"><section><h3>Ритъм, който може да се поддържа</h3><p>Един ясен предматчов бриф. При важна промяна — кратка актуализация. Без постоянен поток от сигнали, който изисква да стоиш пред телефона.</p></section><section><h3>Едни и същи правила за всички</h3><p>FREE и Club се избират преди публикуване. Нито печалбите, нито загубите се прехвърлят между отчетите след края на мача.</p></section></div>`;}
function candidates(){return D.fixtures.filter(f=>f.date===D.date&&Math.min(f.home_stats.n,f.away_stats.n)>=5).sort((a,b)=>Math.min(b.home_stats.n,b.away_stats.n)-Math.min(a.home_stats.n,a.away_stats.n)).slice(0,5);}
function renderDesk(){const cs=candidates();if(!selectionsInitialized){cs.forEach(f=>selected.add(f.id));selectionsInitialized=true;}const rf=cs.find(f=>selected.has(f.id))||cs[0];main.innerHTML=`<div class="page-top"><div><p class="eyebrow">PRIME STUDIO / СИМУЛАЦИЯ НА РЕДАКТОРСКАТА РАБОТА</p><h1 class="page-title">От програма до бриф.</h1><p class="subhead">Данните подготвят работата. Футболният анализ я довършва. Одобрението е за конкретна версия.</p></div>${badge('САМО ЛОКАЛЕН ПРЕГЛЕД','amber')}</div><div class="desk-steps"><div class="step current">01 / АВТОМАТИЧНО<strong>Програмата и историята</strong>Реално подготвен snapshot.</div><div class="step current">02 / С ЧОВЕШКИ СТАРТ<strong>Футболното проучване</strong>Изтегли пакет и го дай на ChatGPT.</div><div class="step">03 / СЛЕД ОДОБРЕНИЕ<strong>Готово за публикуване</strong>В демото публикация не се изпраща.</div></div><div class="desk-grid"><section class="panel"><p class="eyebrow">КАНДИДАТИ / 23 ОКТОМВРИ</p><h2>${cs.length} двубоя за преглед</h2><p>Подборът е по достатъчна история. Това не е класация на „най-сигурните“ прогнози.</p>${cs.map(f=>`<label class="candidate"><input type="checkbox" data-candidate="${esc(f.id)}" ${selected.has(f.id)?'checked':''}><span><b>${esc(f.home.name)}<br>${esc(f.away.name)}</b><small>${f.time} · ${f.league}<br>История ${f.home_stats.n} + ${f.away_stats.n} · няма цена</small></span></label>`).join('')}<button class="btn primary full" style="margin-top:20px" data-action="packet">Изтегли изследователски пакет ↓</button><div class="data-summary"><div><strong>${fmt(D.history_count,0)}</strong><small>РЕАЛНИ РЕЗУЛТАТА</small></div><div><strong>${D.fixtures.length}</strong><small>ПРЕДСТОЯЩИ МАЧА</small></div></div><div class="status-list"><span>OpenLigaDB / ODbL</span><span>Без xG</span><span>Без новини</span><span>Без цени</span></div><p>Подготвянето на този snapshot е пуснато ръчно за прототипа. Нов ежедневен scheduler още не е активиран.</p></section><section class="panel"><p class="eyebrow">ПРЕГЛЕД / ${esc(rf?.home.name)} — ${esc(rf?.away.name)}</p><h2>Провери преди публикуване.</h2><p>Върни структурирания резултат от проучването. Проверяваме двубоя, версията, източниците, риска и актуалността на цената. Примерът използва фиксиран демо час от snapshot-а.</p><label class="visually-hidden" for="review">JSON резултат от футболното проучване</label><textarea id="review" class="review-box" spellcheck="false" placeholder='{"fixture_id":"${esc(rf?.id)}", "thesis":"…", "quote":null}'>${esc(reviewText)}</textarea><div class="desk-actions"><button class="btn small" data-action="review-example">Зареди непълен пример</button><button class="btn small" data-action="review-complete">Симулирай завършена проверка</button><button class="btn small primary" data-action="validate">Провери JSON</button></div><div id="review-checks">${review&&reviewErrors.length===0?'<div class="check-row pass"><span>Версия, източници и цена</span><span>Демо структурата е валидна</span></div>':reviewErrors.length?reviewErrors.map(x=>`<div class="check-row"><span>${esc(x)}</span><span>Чака</span></div>`).join(''):'<div class="check-row"><span>Източници и цена</span><span>Очакват проверка</span></div><div class="check-row"><span>Публикувана селекция</span><span>Няма</span></div>'}</div><div id="approval-result">${simulatedApproval?'<div class="demo-output"><strong>Демо прегледът е одобрен локално.</strong><br>Няма изпращане до Telegram, запис в реален регистър или промяна на сайта.</div>':''}</div><button class="btn primary full" style="margin-top:20px" data-action="approve" ${review&&reviewErrors.length===0?'':'disabled'}>Одобри демо прегледа <span>→</span></button>${review&&reviewErrors.length===0?'<p class="small-text muted">JSON проверката проверява структурата. Самият футболен факт все още изисква човешки прочит на източника.</p>':''}<div class="preview-publish"><h3>Три ясни състояния</h3><p>Кандидат → проучен → одобрен. Липсваща цена или непроверен състав връща мача за проучване. Публикуването в работната версия ще се удостоверява през GitHub.</p></div></section></div>`;}
function currentReviewFixture(){return candidates().find(f=>selected.has(f.id))||candidates()[0];}
function example(complete){const f=currentReviewFixture(),t=D.fetched_utc;return {fixture_id:f.id,snapshot_id:t,market:'over25',audience:'free',thesis:'Демонстрационна теза за отворен двубой, която изисква реално футболно потвърждение.',risk:'Промяна на състава или игровия план може да обезсили головия сценарий.',checked_at:t,team_news_status:complete?'checked':'pending',sources:complete?[{url:'https://news.example.invalid/preview',claim:'Симулирана проверка на състава; не е реална новина.',checked_at:t}]:[],quote:complete?{decimal:1.8,market:'over25',source_url:'https://prices.example.invalid/quote',observed_at:t}:null,simulated:true};}
function validate(){try{review=JSON.parse(reviewText);reviewErrors=E.validateReview(review,currentReviewFixture(),D,{demo:true,now:new Date(D.fetched_utc)});}catch(e){review=null;reviewErrors=['JSON не е валиден. Провери кавичките и запетаите.'];}simulatedApproval=false;renderDesk();if(!reviewErrors.length){$('#review-checks').innerHTML='<div class="check-row pass"><span>Двубой и версия на данните</span><span>Съвпадат</span></div><div class="check-row pass"><span>Източници, теза и риск</span><span>Структурата е валидна</span></div><div class="check-row pass"><span>Цена и час на проверката</span><span>Валидни в демо часа</span></div><p class="notice">Това са симулирани новини и цена. Не могат да преминат production проверката.</p>';}}
function packet(fs){return `PRIME / GOAL RESEARCH PACKET\nВерсия на данните: ${D.fetched_utc}\nРежим: проучване, без право за автоматично публикуване.\nИзточник: OpenLigaDB (ODbL). Данните са датиран snapshot.\n\nМИСИЯ\nПроучи избраните двубои на български. Историческите показатели са отправна точка, не прогноза. Намери актуални първични източници за състави, отсъствия, ротация и игрови контекст. За всеки факт запиши URL, дата на публикация и час на проверката. Не попълвай липсващ факт с предположение. Разграничавай потвърдено от вероятно.\n\nРазрешени пазари: общи голове над/под, голове на отбор над/под, гол/гол. Предложи до една основна селекция за двубой само когато имаш ясна теза, риск и реална актуална цена за точния пазар. Иначе статус WATCH или REJECT. Не наричай историческа честота AI увереност. Не извеждай произволни вероятности.\n\nВърни JSON за всеки двубой с полета fixture_id, snapshot_id, market, audience, thesis, risk, checked_at, team_news_status, sources:[{url,claim,checked_at}], quote:{decimal,market,source_url,observed_at} или null. Всички часове са ISO UTC. За липсваща цена използвай null. Отдели решението от източниците.\n\n${fs.map(f=>`ДВУБОЙ ${f.id}\n${f.home.name} — ${f.away.name}\n${f.league}, ${f.kickoff_utc} / София ${f.date} ${f.time}\nИзточник ${f.source_url}\nДомакин: ${JSON.stringify(f.home_stats)}\nГост: ${JSON.stringify(f.away_stats)}\nДомакински мачове: ${JSON.stringify(f.home_venue)}\nГостувания: ${JSON.stringify(f.away_venue)}\nТекущи xG/новини/цени: НЯМА ДАННИ.\n`).join('\n')}\nНяма реално публикувани прогнози в този прототип.\n`;}
function download(name,text,type='text/plain'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Файлът е подготвен за изтегляне.');}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function modal(title,html){$('#modal-content').innerHTML=`<p class="eyebrow">PRIME / PRODUCT PREVIEW</p><h2 id="modal-title">${title}</h2>${html}`;$('#modal').showModal();}
function render(scroll=true){const route=location.hash.slice(1).split('/')[0]||'today';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===route||route==='match'&&a.dataset.nav==='today';a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='fixtures')renderFixtures();else if(route==='match')renderMatch();else if(route==='record')renderRecord();else if(route==='club')renderClub();else if(route==='desk')renderDesk();else renderToday();document.title=`PRIME · ${{today:'Головият бриф',fixtures:'Програмата',match:findMatch().home.name+' — '+findMatch().away.name,record:'Архивът',club:'Club',desk:'Редакторско студио'}[route]||'Головият бриф'}`;if(scroll)window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='about')modal('Какво е реално тук?',`<p><strong>Реални:</strong> ${D.history_count.toLocaleString('bg-BG')} резултата, ${D.fixtures.length} предстоящи срещи, отборни извадки и начален час от OpenLigaDB. Изтеглени на ${esc(D.fetched_utc)}.</p><p><strong>Примерни:</strong> селекциите, редакторските тези, ценовият праг, новините в симулацията и примерният регистър.</p><p>Работят навигацията, филтрите, подробностите, изследователският пакет, CSV експортът и структурната проверка. Няма автоматичен AI, плащания, изпращане до Telegram или публикуване. Студиото показва UX на бъдещ частен процес; не е защитена администрация.</p>`);
else if(a==='close')$('#modal').close();else if(a==='club-info')modal('Първо доверие. После Club.','<p>Предложението е €9 месечно за допълнително проучване и частен Telegram бриф. Това е ценова хипотеза, която ще проверим след първите реални издания.</p><p>На този етап няма поръчка, регистрация или плащане. Работната версия ще активира достъпа отделно; непубликуваното Club съдържание ще остане частно.</p>');
else if(a==='date'){fixtureDate=b.dataset.date;render(false);}else if(a==='league'){leagueFilter=b.dataset.league;render(false);}else if(a==='matchtab'){matchTab=b.dataset.tab;render(false);}else if(a==='record-real'){recordDemo=false;render(false);}else if(a==='record-demo'){recordDemo=true;render(false);}else if(a==='packet-one'){const f=D.fixtures.find(f=>f.id===b.dataset.id);download(`PRIME_RESEARCH_${f.id.replace(':','_')}.txt`,packet([f]));}else if(a==='packet'){const fs=candidates().filter(f=>selected.has(f.id));if(!fs.length){toast('Избери поне един двубой.');return;}download('PRIME_RESEARCH_2026-10-23.txt',packet(fs));}else if(a==='review-example'||a==='review-complete'){reviewText=JSON.stringify(example(a==='review-complete'),null,2);review=null;reviewErrors=[];simulatedApproval=false;renderDesk();}else if(a==='validate'){reviewText=$('#review').value;validate();}else if(a==='approve'){if(review&&reviewErrors.length===0){simulatedApproval=true;renderDesk();toast('Одобрена е само локалната симулация.');}}else if(a==='export-record'){const r=recordDemo?demoRecord:[];const csv='demo_id,fixture,market,odds,result,audience,synthetic\r\n'+r.map(x=>[x.id,x.name,x.market,x.odds,x.result,x.audience,true].join(',')).join('\r\n');download(recordDemo?'PRIME_DEMO_REGISTER.csv':'PRIME_REGISTER_EMPTY.csv','\uFEFF'+csv,'text/csv');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;renderFixtures();const s=$('#search');s.focus();try{s.setSelectionRange(pos,pos);}catch(_){}}else if(e.target.id==='review'){reviewText=e.target.value;review=null;simulatedApproval=false;const a=document.querySelector('[data-action="approve"]');if(a)a.disabled=true;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-candidate]')){if(e.target.checked)selected.add(e.target.dataset.candidate);else selected.delete(e.target.dataset.candidate);review=null;reviewErrors=[];simulatedApproval=false;const a=document.querySelector('[data-action="approve"]');if(a)a.disabled=true;}});
window.addEventListener('hashchange',()=>{matchTab='analysis';render();});render();
})();
